<div class="page-heading"><div><div class="breadcrumb-line">Finance <span>&rsaquo;</span> <b>Employee Advances</b></div><h1>Employee Advances</h1><p><?= e($isAdmin ? 'Review advance requests from the front desk.' : 'Request an advance for any employee. Admin approval is required.') ?></p></div><?php if (!$isAdmin): ?><button class="btn btn-primary" data-modal-open="cashier-advance-modal">+ Request Advance</button><?php endif; ?></div>
<div class="admin-panel supplier-list-panel"><div class="panel-heading"><h2><?= e($isAdmin ? 'Request Inbox' : 'Request History') ?></h2><span class="text-muted"><?= count($rows) ?> record<?= count($rows) === 1 ? '' : 's' ?></span></div><div class="table-responsive"><table class="table admin-table"><thead><tr><th>Date</th><?php if ($isAdmin): ?><th>Requested By</th><?php endif; ?><th>Employee</th><th>Amount</th><th>Reason</th><th>Status</th><th>Cash Given</th><th>Reviewed</th><th>Receipt</th><th>Action</th></tr></thead><tbody><?php if (!$rows): ?><tr><td colspan="<?= $isAdmin ? 10 : 9 ?>" class="empty-table">No advance requests found.</td></tr><?php else: foreach ($rows as $row): ?><tr><td><?= e($row['advance_date']) ?></td><?php if ($isAdmin): ?><td><strong><?= e($row['cashier_name']) ?></strong></td><?php endif; ?><td><strong><?= e($row['employee_name']) ?></strong></td><td><strong>Rs. <?= number_format((float) $row['amount'], 2) ?></strong></td><td><?= e($row['reason'] ?: '-') ?></td><td><span class="status-badge status-<?= e($row['status']) ?>"><?= e(ucfirst($row['status'])) ?></span></td><td><span class="status-badge status-<?= $row['disbursement_status'] === 'given' ? 'approved' : 'pending' ?>"><?= $row['disbursement_status'] === 'given' ? 'Given' : ($row['status'] === 'approved' ? 'Not given' : '-') ?></span></td><td><?= e($row['reviewer_name'] ? $row['reviewer_name'] . ' / ' . ($row['reviewed_at'] ?? '') : '-') ?></td><td><?php if (!empty($row['receipt_no'])): ?><a href="index.php?page=admin&amp;section=cashier-advance-requests&amp;advance_receipt_id=<?= (int) $row['id'] ?>" class="btn btn-sm btn-outline-primary">View</a><?php else: ?>-<?php endif; ?></td><td><?php if ($isAdmin && $row['disbursement_status'] === 'not_given' && in_array($row['status'], ['pending', 'approved'], true)): ?><a href="index.php?page=admin&amp;section=cashier-advance-requests&amp;advance_edit_id=<?= (int) $row['id'] ?>" class="btn btn-sm btn-outline-secondary">Edit</a><?php endif; ?><?php if ($isAdmin && $row['status'] === 'pending'): ?><form method="post" class="d-flex gap-1 mt-1"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="request_id" value="<?= (int) $row['id'] ?>"><input type="text" name="review_note" class="form-control form-control-sm" placeholder="Note"><button class="btn btn-sm btn-success" name="advance_request_action" value="approve">Accept</button><button class="btn btn-sm btn-outline-danger" name="advance_request_action" value="reject">Reject</button></form><?php elseif ($row['status'] === 'approved' && $row['disbursement_status'] === 'not_given'): ?><form method="post" class="mt-1"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="request_id" value="<?= (int) $row['id'] ?>"><button class="btn btn-sm btn-primary" name="advance_request_action" value="mark_given">Mark as Given</button></form><?php endif; ?></td></tr><?php endforeach; endif; ?></tbody></table></div></div>
<?php if (!$isAdmin): ?><div class="customer-modal-backdrop" id="cashier-advance-modal" hidden><section class="customer-modal" role="dialog" aria-modal="true"><div class="customer-modal-header"><div><span class="modal-eyebrow">Cash request</span><h2>Request Employee Advance</h2></div><button type="button" class="customer-modal-close" data-modal-close>&times;</button></div><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="advance_request_action" value="create"><div class="customer-modal-body"><div class="mb-3"><label class="form-label">Employee *</label><select class="form-select" name="employee_id" required><option value="">Select employee</option><?php foreach ($employeeOptions as $employeeOption): ?><option value="<?= (int) $employeeOption['id'] ?>"><?= e($employeeOption['name'].' ('.$employeeOption['employee_code'].')') ?></option><?php endforeach; ?></select></div><div class="mb-3"><label class="form-label">Advance Date *</label><input class="form-control" type="date" name="advance_date" value="<?= e(date('Y-m-d')) ?>" required></div><div class="mb-3"><label class="form-label">Amount (Rs.) *</label><input class="form-control" type="number" name="amount" min=".01" step=".01" required></div><div><label class="form-label">Reason</label><textarea class="form-control" name="reason" rows="3" placeholder="Optional reason"></textarea></div></div><div class="customer-modal-footer"><button type="button" class="btn btn-light" data-modal-close>Cancel</button><button class="btn btn-primary">Send Request</button></div></form></section></div><?php endif; ?>
